import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

function createNode(config, ctx) {
  const { Group, Mesh, Shape, ShapeGeometry } = ctx.THREE;
  const group = new Group();
  group.name = config.id || 'pricing-badge';

  const width = 1.45;
  const height = 0.34;
  const radius = height * 0.5;

  const roundedShape = (w, h, r) => {
    const shape = new Shape();
    const x = -w * 0.5;
    const y = -h * 0.5;

    shape.moveTo(x + r, y);
    shape.lineTo(x + w - r, y);
    shape.absarc(x + w - r, y + r, r, -Math.PI * 0.5, 0, false);
    shape.lineTo(x + w, y + h - r);
    shape.absarc(x + w - r, y + h - r, r, 0, Math.PI * 0.5, false);
    shape.lineTo(x + r, y + h);
    shape.absarc(x + r, y + h - r, r, Math.PI * 0.5, Math.PI, false);
    shape.lineTo(x, y + r);
    shape.absarc(x + r, y + r, r, Math.PI, Math.PI * 1.5, false);

    return shape;
  };

  const edgeMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    transparent: true,
    opacity: 0.82
  });

  const surfaceMaterial = new MeshBasicNodeMaterial({
    color: '#16161d',
    transparent: true,
    opacity: 0.98
  });

  const edgeGeometry = new ShapeGeometry(
    roundedShape(width + 0.045, height + 0.045, radius + 0.022)
  );
  const surfaceGeometry = new ShapeGeometry(
    roundedShape(width, height, radius)
  );

  const edge = new Mesh(edgeGeometry, edgeMaterial);
  edge.position.z = -0.012;
  edge.name = 'accent-edge';

  const surface = new Mesh(surfaceGeometry, surfaceMaterial);
  surface.name = 'ceramic-surface';

  group.add(edge, surface);

  const timelines = [];
  let disposed = false;
  let texture = null;

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((loadedTexture) => {
      if (disposed) return;
      texture = loadedTexture;
      texture.colorSpace = ctx.THREE.SRGBColorSpace;
      surfaceMaterial.map = texture;
      surfaceMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const animateHover = (active) => {
    const tween = gsap.to(group.position, {
      y: active ? 0.15 : 0,
      duration: active ? 0.28 : 0.36,
      ease: active ? 'power3.out' : 'power2.out',
      overwrite: true
    });
    timelines.push(tween);
  };

  const press = () => {
    const tween = gsap.timeline();
    tween.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'power2.out'
    }).to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.32,
      ease: 'back.out(2)'
    });
    timelines.push(tween);
  };

  const setFocused = (focused) => {
    const tween = gsap.to(edgeMaterial, {
      opacity: focused ? 1 : 0.82,
      duration: 0.22,
      ease: 'power2.out',
      overwrite: true
    });
    timelines.push(tween);
  };

  group.userData.handlers = {
    hover: (active = true) => animateHover(Boolean(active)),
    focus: () => setFocused(true),
    blur: () => setFocused(false),
    click: () => {
      press();
      ctx.emit('hub-pricing.select', {
        id: config.id || 'pricing-badge'
      });
    }
  };

  group.userData.cleanup = () => {
    disposed = true;

    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') timeline.kill();
    }
    timelines.length = 0;

    edgeGeometry.dispose();
    surfaceGeometry.dispose();
    edgeMaterial.dispose();
    surfaceMaterial.dispose();

    if (texture && typeof texture.dispose === 'function') {
      texture.dispose();
    }
  };

  return group;
}

export default createNode;
